[
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 159,
    "summary": "Using n_jobs=-1 oversubscribes each small LightGBM fit. The four models contain only about 17,500 rows and 18 features each, so thread-management overhead dominates useful work.",
    "failure_scenario": "A normal run trains four 400-tree models. On this machine, one representative fit took 1.80 seconds with n_jobs=-1 versus 0.236 seconds with n_jobs=1, a 7.6x slowdown. Use n_jobs=1 or a measured small fixed value. This can reduce the current fitting phase from roughly 7.2 seconds to under 1 second while sharply reducing CPU contention and context switches."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 221,
    "summary": "The three independent backtest fits run sequentially, and the final 2020 fit starts only after all of them finish.",
    "failure_scenario": "Repeated runs and parameter sweeps serialize four independent models. After limiting each model to one thread, the four folds took 1.14 seconds sequentially versus 0.365 seconds through a four-worker ThreadPoolExecutor on this machine. Run the backtests and final fit through a bounded executor with one thread per model, then restore report order. This gives about a 3x wall-time reduction at the cost of modest concurrent model and feature memory."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 10,
    "summary": "LightGBM and Matplotlib are imported at module load even when callers only need data, feature, or metric helpers, or invoke --help.",
    "failure_scenario": "Test collection, short-lived workers, and CLI help pay the complete scientific stack startup cost. Importing forecast_load measured 1.63 seconds and about 200 MB maximum RSS; --help measured 1.23 seconds and about 202 MB. Move LightGBM and plotting imports into build_model and plot_forecast, and guard Axes and Figure imports with TYPE_CHECKING. Utility-only processes can then avoid roughly one second and about 100 MB of startup memory."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 175,
    "summary": "Calendar features are rebuilt for every fold despite heavy overlap between the two-year training windows.",
    "failure_scenario": "The four fits construct eight feature frames covering 70,800 timestamp rows, although only 43,992 distinct timestamps are involved. Profiling attributed about 0.33 seconds to these calls, and each training frame occupies about 2.19 MB. Build one feature matrix for the complete required period and pass positional slices or views into each fit. That reduces row-level feature work by about 38%, constructs the holiday calendar once instead of eight times, and saved roughly 0.18 seconds in local measurements; the cached full table is about 5.45 MB."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 481,
    "summary": "main retains the training series returned by split_training_and_target in _, then recreates the same pre-target slice twice for backtests and the final fit.",
    "failure_scenario": "Each repeated boolean slice scans 50,400 timestamps and allocates another 43,824-row Series of about 701 KB, while the original Series bound to _ remains alive until main returns. Bind the first result as training and pass it to both run_backtests and fit_and_forecast. This removes two scans and two transient allocations and lowers peak live data by about 701 KB."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 116,
    "summary": "Holiday status is calculated through Python date objects and one calendar membership lookup per hour, although the result changes only once per local day.",
    "failure_scenario": "The current four-fold run creates about 70,800 Python date entries and performs about 70,800 holiday lookups; profiling measured 0.051 seconds in membership checks alone. Normalize timestamps to local dates, evaluate each unique day once, and broadcast the result with an indexed or vectorized mapping. This cuts lookups by roughly 24x per feature call, to about 2,950 across the existing calls, or about 1,833 when combined with the shared feature cache."
  }
]

