[
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 224,
    "summary": "The backtest availability guard checks only the forecast window's final timestamp, not whether enough preceding training history exists.",
    "failure_scenario": "A continuous input beginning on 2016-01-03 still contains the complete two-year 2018 to 2019 training window and the 2020 target, so the primary forecast is viable. The 2017 backtest endpoint is present, however, so run_backtests attempts that backtest and fit_and_forecast raises for insufficient history, aborting the entire CLI run before any primary forecast artifacts are written."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 215,
    "summary": "R-squared divides by zero when the actual series is constant, violating the function's otherwise finite-metric contract.",
    "failure_scenario": "For actual values [10, 10, 10], a perfect forecast produces NaN and an imperfect forecast produces negative infinity for r_squared. write_metrics_report then serializes NaN or -Infinity, which strict JSON consumers reject, while the plot and console expose a non-finite metric."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 193,
    "summary": "Metric calculation discards pandas indexes and compares by position, while forecast-table construction aligns the same series by timestamp.",
    "failure_scenario": "If a replacement forecasting implementation returns the correct values on timestamps shifted by one hour, calculate_metrics can report zero error and R-squared 1.0 because both arrays have the same positional values. build_forecast_table then creates the union of the indexes, inserts NaNs, and computes different timestamp-aligned errors, so the JSON metrics, CSV, and plot contradict one another."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 76,
    "summary": "Continuity validation covers the entire supplied dataset before the code isolates the fixed training and target periods.",
    "failure_scenario": "An updated OPSD file can contain every required hour through 2020-01-08 but have one missing provisional hour in September 2020. That later gap is irrelevant to the requested forecast and all backtests, yet load_hourly_load rejects the file before split_training_and_target can discard the unused future observations."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 171,
    "summary": "fit_and_forecast enforces only a minimum observation count and does not re-establish continuity or recency of the training window.",
    "failure_scenario": "A caller can provide more than one year of hourly observations ending on 2019-11-30 and request the 2020-01-01 forecast. The function accepts the data and silently trains through a 31-day gap immediately before the forecast, even though the loader's continuity invariant was bypassed by the direct helper call."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 493,
    "summary": "The three related output artifacts are overwritten independently without atomic publication or a shared run identifier.",
    "failure_scenario": "If the process is interrupted after writing the new CSV or PNG, or the final JSON write fails because of disk or permission issues, the output directory retains a mixture of new and previous-run artifacts. A downstream consumer can pair stale metrics with a new forecast without any field or checksum that reveals the mismatch."
  }
]

