  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 215,
    "summary": "R-squared divides by zero for a constant actual series, so finite valid inputs can produce a non-finite metric.",
    "failure_scenario": "For one observation or repeated nonzero actual values, total_variation is zero. A perfect forecast returns NaN and an imperfect forecast can return negative infinity. write_metrics_report then serializes NaN or Infinity using nonstandard JSON tokens, and the plot and summary display an invalid R-squared value."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 407,
    "summary": "The report, plot, and console summary hard-code the global target period, hour count, and training window instead of deriving them from the supplied ModelRun and table.",
    "failure_scenario": "A supported call to fit_and_forecast for another week or with training_years=1 can be passed to these helpers, but the JSON still claims January 2020 and two training years, while the plot subtitle and console summary also describe the fixed 2020 period. The artifacts then contradict their actual forecast data."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 251,
    "summary": "build_forecast_table does not require identical actual and forecast indexes, while calculate_metrics compares the corresponding arrays positionally.",
    "failure_scenario": "If a forecast has the correct length but shuffled timestamps, metrics describe positional pairs while pandas realigns the CSV rows by timestamp, so the reported metrics do not describe the table or plot. A shifted or partially missing index instead creates an outer union containing NaNs without raising an error."
  },
  {
    "file": "/Users/doob/dev/energy_forecast_ws/dbc151/project/runs/dbc151/forecast_load.py",
    "line": 489,
    "summary": "The CLI publishes three fixed-name output files independently, with no lock or atomic set-level staging.",
    "failure_scenario": "Two forecasts using different --data files and the same --output-dir can interleave writes, leaving the CSV from one run and the plot or metrics from the other. A single run that fails after writing the CSV also leaves a partial output set, potentially alongside stale artifacts from an earlier successful run."
  }
]

